def _build_component_06():
    def rounded(numerator, mode):
        if mode == "half_up":
            return (numerator + 5000) // 10000
        return numerator // 10000

    def solve(data):
        cutoff = data.get("cutoff", 10**9)
        chosen = {}
        for position, event in enumerate(data["events"]):
            sequence = event.get("sequence", 0)
            if sequence > cutoff:
                continue
            event_id = event.get("id", "anonymous:" + str(position))
            key = (sequence, event.get("revision", 0), position)
            if event_id not in chosen or key > chosen[event_id][0]:
                chosen[event_id] = (key, event)

        balances = dict(data.get("opening", {}))
        mode = data["rounding"]
        for _, event in chosen.values():
            if event.get("void", False):
                continue
            raw = event["price"] * event.get("quantity", 1)
            discount = min(10000, max(0, event.get("discount_bp", 0)))
            net = rounded(raw * (10000 - discount), mode)
            tax = rounded(raw * event.get("tax_bp", 0), mode)
            amount = net + tax
            if event.get("kind") == "refund":
                amount = -amount
            account = event.get("account", "default")
            currency = event.get("currency", "USD")
            key = account + "|" + currency
            balances[key] = balances.get(key, 0) + amount
        return {"balances": balances}
    return solve


def _build_component_07():
    def solve(data):
        packages = data["packages"]
        names = sorted(packages, reverse=True)
        features = set(data.get("features", []))
        roots = data["roots"]
        blocked = data.get("blocked", {})
        pins = data.get("pins", {})
        options = []
        row_maps = {}
        for name in names:
            rows = {row["version"]: row for row in packages[name]}
            row_maps[name] = rows
            permitted = [v for v in rows
                         if v not in blocked.get(name, []) and
                         (name not in pins or v == pins[name])]
            options.append([-1] + sorted(permitted))

        def valid(selection):
            installed = {name: version for name, version in zip(names, selection)
                         if version != -1}
            for name, bounds in roots.items():
                version = installed.get(name)
                if version is None or not bounds[0] <= version <= bounds[1]:
                    return False
            graph = {name: [] for name in installed}
            for name, version in installed.items():
                for dep in row_maps[name][version].get("deps", []):
                    feature = dep.get("feature", "")
                    if feature and feature not in features:
                        continue
                    other = installed.get(dep["name"])
                    if other is None or not dep["min"] <= other <= dep["max"]:
                        return False
                    graph[name].append(dep["name"])

            # Installed packages must be exactly the dependency closure of roots.
            reached = set()
            stack = list(roots)
            while stack:
                name = stack.pop()
                if name in reached:
                    continue
                if name not in installed:
                    return False
                reached.add(name)
                stack.extend(graph[name])
            if reached != set(installed):
                return False

            finished, active = set(), set()
            def visit(name):
                if name in active:
                    return False
                if name in finished:
                    return True
                active.add(name)
                if any(not visit(other) for other in graph[name]):
                    return False
                active.remove(name)
                finished.add(name)
                return True
            return all(visit(name) for name in graph)

        best = None
        for selection in product(*options):
            if valid(selection) and (best is None or selection > best):
                best = selection
        if best is None:
            return {"error": "unsatisfiable"}
        return {"versions": {name: version for name, version in zip(names, best)
                              if version != -1}}
    return solve


def _build_component_08():
    def solve(data):
        jobs = data["jobs"]
        k = data["k"]
        blocked = set(data.get("blocked", []))
        mandatory = set(data.get("mandatory", []))
        options = [job for job in jobs if job["id"] not in blocked]
        quotas = data.get("quotas", {})
        best_value = None
        best_ids = None

        for subset in combinations(options, k):
            ids = {job["id"] for job in subset}
            if not mandatory.issubset(ids):
                continue
            counts = {}
            for job in subset:
                counts[job["group"]] = counts.get(job["group"], 0) + 1
            if any(not low <= counts.get(group, 0) <= high
                   for group, (low, high) in quotas.items()):
                continue

            events = []
            for job in subset:
                events.append((job["start"], 1))
                events.append((job["end"], -1))
            # Half-open intervals: process endings before starts at a shared time.
            active = 0
            feasible = True
            for _, change in sorted(events, key=lambda event: (event[0], event[1])):
                active += change
                if active > 2:
                    feasible = False
                    break
            if not feasible:
                continue

            value = sum(job["value"] for job in subset)
            selected = sorted(ids)
            if (best_value is None or value > best_value or
                    (value == best_value and selected < best_ids)):
                best_value, best_ids = value, selected

        if best_value is None:
            return {"error": "impossible"}
        return {"selected": best_ids, "value": best_value}
    return solve


